"""生成项目自有 SVG 示意图，不使用远程图片。"""
from pathlib import Path

OUT = Path(__file__).resolve().parents[1] / 'frontend/assets'
def svg(name, body, bg='#e8e9df'):
    (OUT / f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 500"><rect width="600" height="500" fill="{bg}"/>{body}</svg>', encoding='utf-8')

